#!/usr/bin/env python3

import sys
import os
import argparse
import ctypes
import base64
from ctypes import c_ubyte, c_int, c_size_t, POINTER, byref
import time

# Load brotli libraries
libbrotlienc = ctypes.CDLL("/usr/lib/x86_64-linux-gnu/libbrotlienc.so.1")
libbrotlidec = ctypes.CDLL("/usr/lib/x86_64-linux-gnu/libbrotlidec.so.1")

# Define function signatures
BrotliEncoderCompress = libbrotlienc.BrotliEncoderCompress
BrotliEncoderCompress.argtypes = [c_int, c_int, c_int, c_size_t, POINTER(c_ubyte), POINTER(c_size_t), POINTER(c_ubyte)]
BrotliEncoderCompress.restype = ctypes.c_bool

BrotliDecoderDecompress = libbrotlidec.BrotliDecoderDecompress
BrotliDecoderDecompress.argtypes = [c_size_t, POINTER(c_ubyte), POINTER(c_size_t), POINTER(c_ubyte)]
BrotliDecoderDecompress.restype = c_int

def compress_data(data, quality=11, lgwin=22):
    """Compress data using brotli"""
    if isinstance(data, str):
        data = data.encode()

    input_size = len(data)
    input_arr = (c_ubyte * len(data)).from_buffer_copy(data)

    # Estimate output size
    output_size = max(input_size + 100, 1000)
    output_arr = (c_ubyte * output_size)()

    output_len = ctypes.c_size_t(output_size)

    result = BrotliEncoderCompress(
        quality,        # quality (0-11)
        lgwin,          # lgwin (0, 10-24)
        0,              # mode (0=generic)
        input_size,     # input_size
        input_arr,      # input_buffer
        byref(output_len),  # encoded_size
        output_arr      # encoded_buffer
    )

    if not result:
        raise Exception("Compression failed")

    return bytes(output_arr[:output_len.value])

def decompress_data(data):
    """Decompress data using brotli"""
    if isinstance(data, str):
        data = data.encode()

    input_size = len(data)
    input_arr = (c_ubyte * len(data)).from_buffer_copy(data)

    # Estimate output size
    output_size = input_size * 4
    for attempt in range(3):
        output_arr = (c_ubyte * output_size)()
        output_len = ctypes.c_size_t(output_size)

        result = BrotliDecoderDecompress(
            input_size,     # encoded_size
            input_arr,      # encoded_buffer
            byref(output_len),  # decoded_size
            output_arr      # decoded_buffer
        )

        if result == 1:  # BROTLI_DECODER_RESULT_SUCCESS
            return bytes(output_arr[:output_len.value])
        elif result == 0:  # BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT
            # Need larger output buffer
            output_size *= 2
        else:  # Error
            raise Exception(f"Decompression failed with code {result}")

    raise Exception("Decompression failed: output buffer too small")

def compress_file(input_file, output_file, quality=11, lgwin=22, comment=None):
