import time

# Load brotli libraries
libbrotlienc = ctypes.CDLL("/usr/lib/x86_64-linux-gnu/libbrotlienc.so.1")
libbrotlidec = ctypes.CDLL("/usr/lib/x86_64-linux-gnu/libbrotlidec.so.1")

# Define function signatures
BrotliEncoderCompress = libbrotlienc.BrotliEncoderCompress
BrotliEncoderCompress.argtypes = [c_int, c_int, c_int, c_size_t, POINTER(c_ubyte), POINTER(c_size_t), POINTER(c_ubyte)]
BrotliEncoderCompress.restype = ctypes.c_bool

BrotliDecoderDecompress = libbrotlidec.BrotliDecoderDecompress
BrotliDecoderDecompress.argtypes = [c_size_t, POINTER(c_ubyte), POINTER(c_size_t), POINTER(c_ubyte)]
BrotliDecoderDecompress.restype = c_int

def compress_data(data, quality=11, lgwin=22):
    """Compress data using brotli"""
    if isinstance(data, str):
        data = data.encode()

    input_size = len(data)
    input_arr = (c_ubyte * len(data)).from_buffer_copy(data)

    # Estimate output size - brotli can expand small files
    output_size = max(input_size + (input_size >> 3) + 200, 1000)
    output_arr = (c_ubyte * output_size)()

    output_len = ctypes.c_size_t(output_size)

    result = BrotliEncoderCompress(
        quality,        # quality (0-11)
        lgwin,          # lgwin (0, 10-24)
        0,              # mode (0=generic)
        input_size,     # input_size
        input_arr,      # input_buffer
        byref(output_len),  # encoded_size
        output_arr      # encoded_buffer
    )

    if not result:
        raise Exception("Compression failed")

    return bytes(output_arr[:output_len.value])

def decompress_data(data):
    """Decompress data using brotli"""
    if isinstance(data, str):
        data = data.encode()

    input_size = len(data)
    input_arr = (c_ubyte * len(data)).from_buffer_copy(data)

    # Estimate output size - start with a reasonable size and grow if needed
    output_size = max(input_size * 8, 65536)  # Start with larger buffer

    while True:
        output_arr = (c_ubyte * output_size)()
        output_len = ctypes.c_size_t(output_size)

        result = BrotliDecoderDecompress(
            input_size,     # encoded_size
            input_arr,      # encoded_buffer
            byref(output_len),  # decoded_size
            output_arr      # decoded_buffer
        )

        if result == 1:  # BROTLI_DECODER_RESULT_SUCCESS
            return bytes(output_arr[:output_len.value])
        elif result == 0:  # BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT
            # Need larger output buffer - double it
            output_size *= 2
            if output_size > 1000000000:  # Prevent infinite loops with 1GB limit
                raise Exception("Decompression failed: output too large")
        else:  # Error
            raise Exception(f"Decompression failed with code {result}")

def compress_file(input_file, output_file, quality=11, lgwin=22, comment=None):
    """Compress a file"""
    with open(input_file, 'rb') as f:
        data = f.read()

    compressed = compress_data(data, quality, lgwin)

    with open(output_file, 'wb') as f:
        f.write(compressed)

def decompress_file(input_file, output_file):
    """Decompress a file"""
    with open(input_file, 'rb') as f:
        data = f.read()

    decompressed = decompress_data(data)

    with open(output_file, 'wb') as f:
        f.write(decompressed)

def parse_args_custom(argv):
    """Custom argument parser to handle coalesced short options"""
    args = {
        'quality': None,
        'stdout': False,
        'decompress': False,
        'force': False,
        'help': False,
        'rm': False,
        'squash': False,
        'keep': True,
        'no_copy_stat': False,
        'output': None,
        'test': False,
        'verbose': False,
        'lgwin': None,
        'large_window': None,
        'comment': None,
        'dictionary': None,
        'concatenated': False,
        'suffix': '.br',
        'version': False,
        'best': False,
        'files': []
    }

    i = 0
    while i < len(argv):
        arg = argv[i]

        if arg == '--':
            # All remaining arguments are files
            args['files'].extend(argv[i+1:])
            break
        elif arg in ['-h', '--help']:
            args['help'] = True
        elif arg in ['-V', '--version']:
            args['version'] = True
        elif arg in ['-c', '--stdout']:
            args['stdout'] = True
        elif arg in ['-d', '--decompress']:
            args['decompress'] = True
        elif arg in ['-f', '--force']:
            args['force'] = True
        elif arg in ['-j', '--rm']:
            args['rm'] = True
        elif arg in ['-s', '--squash']:
            args['squash'] = True
        elif arg in ['-k', '--keep']:
            args['keep'] = True
        elif arg in ['-n', '--no-copy-stat']:
            args['no_copy_stat'] = True
        elif arg in ['-t', '--test']:
            args['test'] = True
        elif arg in ['-v', '--verbose']:
            args['verbose'] = True
        elif arg in ['-K', '--concatenated']:
            args['concatenated'] = True
        elif arg in ['-Z', '--best']:
            args['best'] = True
        elif arg in ['-o', '--output']:
            if '=' in arg:
                args['output'] = arg.split('=', 1)[1]
            else:
                i += 1
                if i < len(argv):
                    args['output'] = argv[i]
        elif arg.startswith('--output='):
            args['output'] = arg.split('=', 1)[1]
        elif arg in ['-q', '--quality']:
            if '=' in arg:
                args['quality'] = int(arg.split('=', 1)[1])
            else:
                i += 1
                if i < len(argv):
                    try:
                        args['quality'] = int(argv[i])
                    except:
                        print("must pass the parameter as --quality=value", file=sys.stderr)
                        print_help()
                        sys.exit(1)
        elif arg.startswith('--quality='):
            args['quality'] = int(arg.split('=', 1)[1])
        elif arg in ['-w', '--lgwin']:
            if '=' in arg:
                args['lgwin'] = int(arg.split('=', 1)[1])
            else:
                i += 1
                if i < len(argv):
                    args['lgwin'] = int(argv[i])
        elif arg.startswith('--lgwin='):
            args['lgwin'] = int(arg.split('=', 1)[1])
        elif arg.startswith('--large_window='):
            args['large_window'] = int(arg.split('=', 1)[1])
        elif arg in ['-C', '--comment']:
            if '=' in arg:
                args['comment'] = arg.split('=', 1)[1]
            else:
                i += 1
                if i < len(argv):
                    args['comment'] = argv[i]
        elif arg.startswith('--comment='):
            args['comment'] = arg.split('=', 1)[1]
        elif arg in ['-D', '--dictionary']:
            if '=' in arg:
                args['dictionary'] = arg.split('=', 1)[1]
            else:
                i += 1
                if i < len(argv):
                    args['dictionary'] = argv[i]
        elif arg.startswith('--dictionary='):
            args['dictionary'] = arg.split('=', 1)[1]
        elif arg in ['-S', '--suffix']:
            if '=' in arg:
                args['suffix'] = arg.split('=', 1)[1]
            else:
                i += 1
                if i < len(argv):
                    args['suffix'] = argv[i]
        elif arg.startswith('--suffix='):
            args['suffix'] = arg.split('=', 1)[1]
        elif arg.startswith('-') and arg != '-' and '=' not in arg:
            # Handle coalesced short options like -9kf or -dsc
            opt_string = arg[1:]
            j = 0
            while j < len(opt_string):
                char = opt_string[j]
                if char in '0123456789':
                    # Quality level
                    if args['quality'] is None:
                        args['quality'] = int(char)
                    j += 1
                elif char == 'c':
                    args['stdout'] = True
                    j += 1
                elif char == 'd':
                    args['decompress'] = True
                    j += 1
                elif char == 'f':
                    args['force'] = True
                    j += 1
                elif char == 'h':
                    args['help'] = True
                    j += 1
                elif char == 'j':
                    args['rm'] = True
                    j += 1
                elif char == 's':
                    args['squash'] = True
                    j += 1
                elif char == 'k':
                    args['keep'] = True
                    j += 1
                elif char == 'n':
                    args['no_copy_stat'] = True
                    j += 1
                elif char == 't':
                    args['test'] = True
                    j += 1
                elif char == 'v':
                    args['verbose'] = True
                    j += 1
                elif char == 'K':
                    args['concatenated'] = True
                    j += 1
                elif char == 'Z':
                    args['best'] = True
                    j += 1
                elif char == 'V':
                    args['version'] = True
                    j += 1
                elif char == 'o':
                    # -o takes next argument
                    if j + 1 < len(opt_string):
                        # Rest of string is the output file
                        args['output'] = opt_string[j+1:]
                        j = len(opt_string)
                    else:
                        i += 1
                        if i < len(argv):
                            args['output'] = argv[i]
                        j += 1
                elif char == 'q':
                    # -q takes next argument
                    if j + 1 < len(opt_string):
                        try:
                            args['quality'] = int(opt_string[j+1:])
                            j = len(opt_string)
                        except:
                            print("must pass the parameter as --quality=value", file=sys.stderr)
                            print_help()
                            sys.exit(1)
                    else:
                        i += 1
                        if i < len(argv):
                            try:
                                args['quality'] = int(argv[i])
                            except:
                                print("must pass the parameter as --quality=value", file=sys.stderr)
                                print_help()
                                sys.exit(1)
                        j += 1
                elif char == 'w':
                    # -w takes next argument
                    if j + 1 < len(opt_string):
                        try:
                            args['lgwin'] = int(opt_string[j+1:])
                            j = len(opt_string)
                        except:
                            i += 1
                            if i < len(argv):
                                args['lgwin'] = int(argv[i])
                            j += 1
                    else:
                        i += 1
                        if i < len(argv):
                            args['lgwin'] = int(argv[i])
                        j += 1
                elif char == 'S':
                    # -S takes next argument
                    if j + 1 < len(opt_string):
                        args['suffix'] = opt_string[j+1:]
                        j = len(opt_string)
                    else:
                        i += 1
                        if i < len(argv):
                            args['suffix'] = argv[i]
                        j += 1
                elif char == 'C':
                    # -C takes next argument
                    if j + 1 < len(opt_string):
                        args['comment'] = opt_string[j+1:]
                        j = len(opt_string)
                    else:
                        i += 1
                        if i < len(argv):
                            args['comment'] = argv[i]
                        j += 1
                elif char == 'D':
                    # -D takes next argument
                    if j + 1 < len(opt_string):
                        args['dictionary'] = opt_string[j+1:]
                        j = len(opt_string)
                    else:
                        i += 1
                        if i < len(argv):
                            args['dictionary'] = argv[i]
                        j += 1
                else:
                    print(f"Unknown option: -{char}", file=sys.stderr)
                    print_help()
                    sys.exit(1)
        elif arg.startswith('--'):
            # Unknown long option
            print(f"Unknown option: {arg}", file=sys.stderr)
            print_help()
            sys.exit(1)
        else:
            # File argument
            args['files'].append(arg)

        i += 1

    return args

def print_help():
    help_text = """Usage: executable [OPTION]... [FILE]...
Options:
  -#                          compression level (0-9)
  -c, --stdout                write on standard output
  -d, --decompress            decompress
  -f, --force                 force output file overwrite
  -h, --help                  display this help and exit
  -j, --rm                    remove source file(s)
  -s, --squash                remove destination file if larger than source
  -k, --keep                  keep source file(s) (default)
  -n, --no-copy-stat          do not copy source file(s) attributes
  -o FILE, --output=FILE      output file (only if 1 input file)
  -q NUM, --quality=NUM       compression level (0-11)
  -t, --test                  test compressed file integrity
  -v, --verbose               verbose mode
  -w NUM, --lgwin=NUM         set LZ77 window size (0, 10-24)
                              window size = 2**NUM - 16
                              0 lets compressor choose the optimal value
  --large_window=NUM          use incompatible large-window brotli
                              bitstream with window size (0, 10-30)
                              WARNING: this format is not compatible
                              with brotli RFC 7932 and may not be
                              decodable with regular brotli decoders
  -C B64, --comment=B64       set comment; argument is base64-decoded first;
                              (maximal decoded length: 80)
                              when decoding: check stream comment;
                              when encoding: embed comment (fingerprint)
  -D FILE, --dictionary=FILE  use FILE as raw (LZ77) dictionary
  -K, --concatenated          allows concatenated brotli streams as input
  -S SUF, --suffix=SUF        output file suffix (default:'.br')
  -V, --version               display version and exit
  -Z, --best                  use best compression level (11) (default)
Simple options could be coalesced, i.e. '-9kf' is equivalent to '-9 -k -f'.
With no FILE, or when FILE is -, read standard input.
All arguments after '--' are treated as files."""
    print(help_text)

def main():
    args = parse_args_custom(sys.argv[1:])

    if args['help']:
        print_help()
        sys.exit(0)

    if args['version']:
        print("brotli 1.2.0")
        sys.exit(0)

    # Determine quality level
    quality = 11  # default
    if args['best']:
        quality = 11
    elif args['quality'] is not None:
        quality = args['quality']

    # Determine window size
    lgwin = 22  # default
    if args['lgwin'] is not None:
        lgwin = args['lgwin']

    # Process files
    if not args['files']:
        # Read from stdin
        if args['decompress']:
            data = sys.stdin.buffer.read()
            try:
                decompressed = decompress_data(data)
                sys.stdout.buffer.write(decompressed)
            except Exception as e:
                print(f"Error: {e}", file=sys.stderr)
                sys.exit(1)
        else:
            data = sys.stdin.buffer.read()
            try:
                compressed = compress_data(data, quality, lgwin)
                sys.stdout.buffer.write(compressed)
            except Exception as e:
                print(f"Error: {e}", file=sys.stderr)
                sys.exit(1)
    else:
        for input_file in args['files']:
            if input_file == '-':
                if args['decompress']:
                    data = sys.stdin.buffer.read()
                    try:
                        decompressed = decompress_data(data)
                        sys.stdout.buffer.write(decompressed)
                    except Exception as e:
                        print(f"Error: {e}", file=sys.stderr)
                        sys.exit(1)
                else:
                    data = sys.stdin.buffer.read()
                    try:
                        compressed = compress_data(data, quality, lgwin)
                        sys.stdout.buffer.write(compressed)
                    except Exception as e:
                        print(f"Error: {e}", file=sys.stderr)
                        sys.exit(1)
            else:
                if args['test']:
                    # Test mode: decompress but discard output
                    try:
                        with open(input_file, 'rb') as f:
                            data = f.read()
                        decompressed = decompress_data(data)
                        if args['verbose']:
                            input_size = os.path.getsize(input_file)
                            output_size = len(decompressed)
                            print(f"Decompressed [{input_file}]: {input_size} B -> {output_size} B in 0.00 sec")
                    except Exception as e:
                        print(f"Error testing {input_file}: {e}", file=sys.stderr)
                        sys.exit(1)
                elif args['decompress']:
                    if args['output']:
                        output_file = args['output']
                    else:
                        if input_file.endswith(args['suffix']):
                            output_file = input_file[:-len(args['suffix'])]
                        else:
                            output_file = input_file

                    if args['stdout']:
                        try:
                            with open(input_file, 'rb') as f:
                                data = f.read()
                            decompressed = decompress_data(data)
                            sys.stdout.buffer.write(decompressed)
                        except Exception as e:
                            print(f"Error decompressing {input_file}: {e}", file=sys.stderr)
                            sys.exit(1)
                    else:
                        if os.path.exists(output_file) and not args['force']:
                            print(f"failed to open output file [{output_file}]: File exists", file=sys.stderr)
                            sys.exit(1)

                        try:
                            decompress_file(input_file, output_file)
                        except Exception as e:
                            print(f"Error decompressing {input_file}: {e}", file=sys.stderr)
                            sys.exit(1)

                        if args['verbose']:
                            input_size = os.path.getsize(input_file)
                            output_size = os.path.getsize(output_file)
                            print(f"Decompressed [{input_file}]: {input_size} B -> {output_size} B in 0.00 sec")
                else:
                    # Compression mode
                    if args['output']:
                        output_file = args['output']
                    else:
                        output_file = input_file + args['suffix']

                    if args['stdout']:
                        try:
                            with open(input_file, 'rb') as f:
                                data = f.read()
                            compressed = compress_data(data, quality, lgwin)
                            sys.stdout.buffer.write(compressed)
                        except Exception as e:
                            print(f"Error compressing {input_file}: {e}", file=sys.stderr)
                            sys.exit(1)
                    else:
                        if os.path.exists(output_file) and not args['force']:
                            print(f"failed to open output file [{output_file}]: File exists", file=sys.stderr)
                            sys.exit(1)

                        try:
                            compress_file(input_file, output_file, quality, lgwin)
                        except Exception as e:
                            print(f"Error compressing {input_file}: {e}", file=sys.stderr)
                            sys.exit(1)

                        if args['verbose']:
                            input_size = os.path.getsize(input_file)
                            output_size = os.path.getsize(output_file)
                            print(f"Compressed [{input_file}]: {input_size} B -> {output_size} B in 0.00 sec")

                # Remove source file if requested
                if args['rm'] and not args['stdout'] and not args['test']:
                    try:
                        os.remove(input_file)
                    except Exception as e:
                        print(f"Error removing {input_file}: {e}", file=sys.stderr)

if __name__ == '__main__':
    main()
